// ============================================================
// READ ENGAGEMENT SCORES FROM CANONICAL FIELDS
// ============================================================
// Reads canon_engagement_score and canon_engagement_status
// which are written by:
//   - DEMO SEED v1.1 (for demos)
//   - Nightly Scorer workflow (for production)
//
// This approach avoids HubSpot's read-only native fields
// while giving us full control over the data story.
// ============================================================

const response = $input.first().json;
const contacts = response.results || [];

function scoreColor(score) {
  if (score >= 70) return 'good';
  if (score >= 50) return 'warning';
  return 'danger';
}

// ---- Parse and structure each contact ----
const scoredContacts = contacts.map(contact => {
  const p = contact.properties || {};

  const engagementScore  = parseInt(p.canon_engagement_score  || '0', 10);
  const engagementStatus = p.canon_engagement_status || 'Unknown';
  const daysSince        = parseInt(p.canon_days_since_engagement || '0', 10);
  const lastCalculated   = p.canon_engagement_last_calculated || null;

  return {
    id:               contact.id,
    name:             [p.firstname, p.lastname].filter(Boolean).join(' ') || '(No name)',
    email:            p.email || '—',
    jobTitle:         p.jobtitle || '—',
    company:          p.company || '—',
    lifecycleStage:   p.lifecyclestage || '—',
    seniority:        p.canon_seniority || '—',
    persona:          p.canon_persona || '—',
    dataConfidence:   parseInt(p.canon_data_confidence || '0', 10),

    // Canonical engagement fields
    engagementScore,
    engagementStatus,
    daysSinceEngagement: daysSince,
    lastCalculated,

    hubspotUrl: `https://app-na2.hubspot.com/contacts/243444428/record/0-1/${contact.id}`
  };
});

// ---- Aggregate status counts ----
const statusCounts = { 'Active': 0, 'At Risk': 0, 'Cold': 0, 'Dormant': 0, 'Opted Out': 0, 'Unknown': 0 };
scoredContacts.forEach(c => {
  if (statusCounts[c.engagementStatus] !== undefined) {
    statusCounts[c.engagementStatus]++;
  } else {
    statusCounts['Unknown']++;
  }
});

// Remove Unknown from counts if empty
if (statusCounts['Unknown'] === 0) delete statusCounts['Unknown'];

const flaggedContacts = scoredContacts.filter(
  c => !['Active'].includes(c.engagementStatus)
);

const avgScore = scoredContacts.length > 0
  ? Math.round(scoredContacts.reduce((sum, c) => sum + c.engagementScore, 0) / scoredContacts.length)
  : 0;

console.log(`[ENGAGEMENT CHECK] ${scoredContacts.length} contacts | avg score: ${avgScore} | flagged: ${flaggedContacts.length}`);

return [{
  json: {
    allContacts:     scoredContacts,
    flaggedContacts: flaggedContacts,
    statusCounts,
    totalContacts:   scoredContacts.length,
    totalFlagged:    flaggedContacts.length,
    avgScore,
    calculatedAt:    new Date().toISOString()
  }
}];

// ============================================================
// BUILD ENGAGEMENT HEALTH REPORT
// ============================================================

const data = $input.first().json;
const {
  allContacts, flaggedContacts, statusCounts,
  totalContacts, totalFlagged, avgScore, calculatedAt
} = data;

const reportDate = new Date().toLocaleDateString('en-US', {
  year: 'numeric', month: 'long', day: 'numeric'
});
const reportTime = new Date().toLocaleTimeString('en-US', {
  hour: '2-digit', minute: '2-digit'
});

function escHtml(str) {
  if (!str && str !== 0) return '';
  return String(str)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;')
    .replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

function statusColor(status) {
  const map = {
    'Active':    '#00A854', 'At Risk':   '#F5A623',
    'Cold':      '#ea580c', 'Dormant':   '#E74C3C',
    'Opted Out': '#6c757d', 'Unknown':   '#9ca3af'
  };
  return map[status] || '#495057';
}

function statusBg(status) {
  const map = {
    'Active':    '#dcfce7', 'At Risk':   '#fef3c7',
    'Cold':      '#ffedd5', 'Dormant':   '#fee2e2',
    'Opted Out': '#f3f4f6', 'Unknown':   '#f9fafb'
  };
  return map[status] || '#f3f4f6';
}

function scoreColor(score) {
  if (score >= 70) return '#00A854';
  if (score >= 50) return '#F5A623';
  if (score >= 30) return '#ea580c';
  return '#E74C3C';
}

function scoreBg(score) {
  if (score >= 70) return '#dcfce7';
  if (score >= 50) return '#fef3c7';
  if (score >= 30) return '#ffedd5';
  return '#fee2e2';
}

function formatDays(days) {
  if (!days && days !== 0) return '—';
  if (days === 0) return 'Today';
  if (days === 1) return '1 day ago';
  if (days < 30)  return `${days}d ago`;
  if (days < 365) return `${Math.floor(days / 30)}mo ago`;
  return `${Math.floor(days / 365)}yr ago`;
}

function overallGrade(avgScore, pctFlagged) {
  if (avgScore >= 80 && pctFlagged < 10) return { grade: 'A', label: 'Healthy' };
  if (avgScore >= 65 && pctFlagged < 25) return { grade: 'B', label: 'Good' };
  if (avgScore >= 50 && pctFlagged < 40) return { grade: 'C', label: 'Needs Attention' };
  if (avgScore >= 35)                    return { grade: 'D', label: 'At Risk' };
  return                                        { grade: 'F', label: 'Critical' };
}

const pctFlagged = totalContacts > 0
  ? Math.round((totalFlagged / totalContacts) * 100)
  : 0;

const health = overallGrade(avgScore, pctFlagged);
const gradeColors = { A: '#00A854', B: '#2C7BE5', C: '#F5A623', D: '#ea580c', F: '#E74C3C' };
const gradeColor = gradeColors[health.grade] || '#495057';

// ---- Build table rows for flagged contacts ----
const tableRows = flaggedContacts.map(c => `
  <tr>
    <td>
      <a href="${c.hubspotUrl}" target="_blank"
         style="color:#1A3A5C;text-decoration:none;font-weight:600">
        ${escHtml(c.name)}
      </a>
      <div style="font-size:11px;color:#6c757d;margin-top:2px">${escHtml(c.email)}</div>
      ${c.company !== '—' ? `<div style="font-size:11px;color:#9ca3af">${escHtml(c.company)}</div>` : ''}
    </td>
    <td>
      <span style="display:inline-block;padding:3px 10px;border-radius:12px;
        font-size:12px;font-weight:600;
        background:${statusBg(c.engagementStatus)};
        color:${statusColor(c.engagementStatus)}">
        ${escHtml(c.engagementStatus)}
      </span>
    </td>
    <td style="text-align:center">
      <span style="display:inline-flex;align-items:center;justify-content:center;
        width:36px;height:36px;border-radius:50%;font-weight:700;font-size:13px;
        background:${scoreBg(c.engagementScore)};color:${scoreColor(c.engagementScore)}">
        ${c.engagementScore}
      </span>
    </td>
    <td style="font-size:12px;color:#6c757d;text-align:center">
      ${escHtml(formatDays(c.daysSinceEngagement))}
    </td>
    <td style="font-size:12px;color:#9ca3af">
      ${escHtml(c.seniority !== '—' ? c.seniority : '')}
    </td>
    <td style="font-size:12px;color:#9ca3af">
      ${c.dataConfidence > 0
        ? `<span style="color:${scoreColor(c.dataConfidence)}">${c.dataConfidence}</span>`
        : '—'
      }
    </td>
  </tr>
`).join('');

// ---- Build full HTML report ----
const html = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Engagement Health Report — ${reportDate}</title>
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }
  body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Arial, sans-serif; color: #495057; background: #fff; line-height: 1.6; }
  .container { max-width: 1100px; margin: 0 auto; padding: 40px 32px; }
  .header { border-bottom: 3px solid #1A3A5C; padding-bottom: 20px; margin-bottom: 30px; }
  .header h1 { font-size: 28px; color: #1A3A5C; margin-bottom: 4px; }
  .header .meta { font-size: 14px; color: #6c757d; }
  .score-card { display: flex; border-radius: 8px; overflow: hidden; margin-bottom: 30px; }
  .score-badge { padding: 24px 32px; display: flex; flex-direction: column; align-items: center; justify-content: center; min-width: 110px; }
  .score-badge .grade { font-size: 48px; font-weight: 800; color: #fff; line-height: 1; }
  .score-badge .label { font-size: 11px; color: rgba(255,255,255,0.85); margin-top: 4px; text-transform: uppercase; letter-spacing: 0.08em; }
  .score-body { background: #E8F4FD; padding: 20px 24px; flex: 1; }
  .score-body h3 { font-size: 16px; color: #1A3A5C; margin-bottom: 6px; }
  .score-body p { font-size: 14px; color: #495057; }
  .stat-grid { display: flex; gap: 12px; margin-bottom: 28px; flex-wrap: wrap; }
  .stat-card { flex: 1; min-width: 110px; padding: 16px; border-radius: 6px; text-align: center; }
  .stat-card .val { font-size: 32px; font-weight: 800; }
  .stat-card .lbl { font-size: 11px; color: #6c757d; margin-top: 4px; text-transform: uppercase; letter-spacing: 0.05em; }
  .breakdown { display: flex; gap: 8px; margin-bottom: 16px; flex-wrap: wrap; }
  .breakdown-item { flex: 1; min-width: 100px; padding: 12px 16px; border-radius: 6px; display: flex; align-items: center; gap: 10px; }
  .breakdown-item .dot { width: 10px; height: 10px; border-radius: 50%; flex-shrink: 0; }
  .breakdown-item .count { font-size: 22px; font-weight: 700; }
  .breakdown-item .name { font-size: 11px; color: #6c757d; }
  h2 { font-size: 20px; color: #1A3A5C; margin: 30px 0 16px; padding-bottom: 8px; border-bottom: 2px solid #E8F4FD; }
  table { width: 100%; border-collapse: collapse; font-size: 13px; margin-bottom: 20px; }
  thead { background: #1A3A5C; color: #fff; }
  thead th { padding: 10px 14px; text-align: left; font-size: 11px; text-transform: uppercase; letter-spacing: 0.06em; font-weight: 600; }
  tbody tr { border-bottom: 1px solid #f3f4f6; }
  tbody tr:hover { background: #fafafa; }
  tbody td { padding: 12px 14px; vertical-align: middle; }
  .empty-state { text-align: center; padding: 60px; color: #6b7280; }
  .footer { margin-top: 40px; padding-top: 16px; border-top: 1px solid #DEE2E6; font-size: 12px; color: #adb5bd; font-style: italic; }
</style>
</head>
<body>
<div class="container">

  <div class="header">
    <h1>📊 Engagement Health Report</h1>
    <div class="meta">
      HubSpot Portal 243444428 &nbsp;|&nbsp;
      ${reportDate} at ${reportTime} &nbsp;|&nbsp;
      ${totalContacts} contacts analyzed
    </div>
  </div>

  <div class="score-card">
    <div class="score-badge" style="background:${gradeColor}">
      <div class="grade">${health.grade}</div>
      <div class="label">${health.label}</div>
    </div>
    <div class="score-body">
      <h3>Engagement Health Overview</h3>
      <p>
        ${totalContacts} contacts analyzed. Average engagement score: <strong>${avgScore}/100</strong>.
        ${totalFlagged === 0
          ? 'All contacts show healthy engagement patterns.'
          : `${totalFlagged} contact${totalFlagged === 1 ? '' : 's'} (${pctFlagged}%) flagged for review. At Risk and Cold contacts should be prioritized for re-engagement before they go Dormant.`
        }
      </p>
    </div>
  </div>

  <div class="stat-grid">
    <div class="stat-card" style="background:#f3f4f6">
      <div class="val" style="color:#1A3A5C">${totalContacts}</div>
      <div class="lbl">Total Analyzed</div>
    </div>
    <div class="stat-card" style="background:#f3f4f6">
      <div class="val" style="color:${scoreColor(avgScore)}">${avgScore}</div>
      <div class="lbl">Avg Score</div>
    </div>
    <div class="stat-card" style="background:#fee2e2">
      <div class="val" style="color:#E74C3C">${totalFlagged}</div>
      <div class="lbl">Flagged</div>
    </div>
    <div class="stat-card" style="background:#f3f4f6">
      <div class="val" style="color:#495057">${pctFlagged}%</div>
      <div class="lbl">Flagged Rate</div>
    </div>
  </div>

  <h2>Status Breakdown</h2>
  <div class="breakdown">
    ${ ['Active','At Risk','Cold','Dormant','Opted Out'].map(status =>
      (statusCounts[status] || 0) > 0 ? `
      <div class="breakdown-item" style="background:${statusBg(status)}">
        <div class="dot" style="background:${statusColor(status)}"></div>
        <div>
          <div class="count" style="color:${statusColor(status)}">${statusCounts[status] || 0}</div>
          <div class="name">${status}</div>
        </div>
      </div>` : ''
    ).join('') }
  </div>

  ${ flaggedContacts.length === 0 ? `
  <div class="empty-state" style="margin-top:30px">
    <div style="font-size:48px;margin-bottom:16px">✅</div>
    <div style="font-size:18px;font-weight:600;color:#374151">No flagged contacts</div>
    <div style="margin-top:8px">All contacts show Active engagement status.</div>
  </div>
  ` : `
  <h2>Flagged Contacts
    <span style="font-size:14px;font-weight:400;color:#6c757d;margin-left:8px">— sorted by score (lowest first)</span>
  </h2>
  <table>
    <thead>
      <tr>
        <th>Contact</th>
        <th>Status</th>
        <th style="text-align:center">Engagement Score</th>
        <th style="text-align:center">Last Engagement</th>
        <th>Seniority</th>
        <th>Data Confidence</th>
      </tr>
    </thead>
    <tbody>${tableRows}</tbody>
  </table>
  `}

  <div class="footer">
    Engagement Intelligence Engine v1.1 &nbsp;|&nbsp;
    Generated via /engagement-check &nbsp;|&nbsp;
    <a href="https://app-na2.hubspot.com/contacts/243444428" style="color:#adb5bd">Open HubSpot</a>
  </div>

</div>
</body>
</html>`;

// ---- Slack summary message ----
const statusLine = Object.entries(statusCounts)
  .filter(([, count]) => count > 0)
  .map(([status, count]) => `${count} ${status}`)
  .join(' · ');

const slackSummary = totalFlagged === 0
  ? `✅ *Engagement Health — All Clear*\nAll ${totalContacts} contacts show Active engagement. Avg score: *${avgScore}/100*.`
  : `📊 *Engagement Health Report — Grade: ${health.grade} (${health.label})*\n${totalContacts} contacts analyzed · Avg score: *${avgScore}/100*\n\n${statusLine}\n\n${totalFlagged} contact${totalFlagged === 1 ? '' : 's'} flagged. Full report attached.`;

const buffer = Buffer.from(html, 'utf-8');
const dateStr = new Date().toISOString().slice(0, 10);
const filename = `engagement-report-${dateStr}.html`;

return [{
  json: {
    slackSummary,
    totalContacts,
    totalFlagged,
    avgScore,
    healthGrade:    health.grade,
    reportFilename: filename,
    reportSize:     buffer.length
  },
  binary: {
    report: await this.helpers.prepareBinaryData(buffer, filename, 'text/html')
  }
}];

const uploadData = $input.first().json;
const binaryData = $('Build Report').first().binary;
return [{
  json: { upload_url: uploadData.upload_url, file_id: uploadData.file_id },
  binary: binaryData
}];

